import{_ as e,o as l,c as i,a4 as t}from"./chunks/framework.BRzJ4ijD.js";const f=JSON.parse('{"title":"第二部分 · 操作系统","description":"","frontmatter":{},"headers":[],"relativePath":"os/index.md","filePath":"os/README.md","lastUpdated":1788475713000}'),r={name:"os/index.md"};function o(n,a,s,c,h,d){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="第二部分-·-操作系统" tabindex="-1">第二部分 · 操作系统 <a class="header-anchor" href="#第二部分-·-操作系统" aria-label="Permalink to &quot;第二部分 · 操作系统&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>操作系统把硬件&quot;驯化&quot;成你可以写代码的虚拟机：它把 CPU 时间切成片让多个程序同跑、把内存切成页让进程互不踩脚、把磁盘抽象成字节流让 IO 透明、把进程间冲突变成锁与同步原语——<strong>你写 hello world 时调用的每个 printf、每个 malloc、每个 epoll 都至少穿过这两层抽象</strong>。理解 OS 就是理解你写的代码底下被自动做了什么、什么时候会失效、失效的代价。</p><h2 id="这一部分的章节" tabindex="-1">这一部分的章节 <a class="header-anchor" href="#这一部分的章节" aria-label="Permalink to &quot;这一部分的章节&quot;">​</a></h2><ul><li><a href="./memory/">内存</a></li><li><a href="./fs/">文件系统</a></li><li><a href="./sched/">进程与线程调度</a></li><li><a href="./lock/">锁与同步原语</a></li><li><a href="./virtualization">虚拟化与容器</a></li><li><a href="./net/">IO 与网络栈</a></li></ul><h2 id="阅读策略" tabindex="-1">阅读策略 <a class="header-anchor" href="#阅读策略" aria-label="Permalink to &quot;阅读策略&quot;">​</a></h2><p>读完这一部分，你得能回答：</p><ul><li><code>malloc(1M)</code> 实际返回到 use 之前 Linux 内核做了什么？</li><li>为什么线程间抢占的 cache line 是性能杀手？</li><li>为什么 epoll 边沿触发要配 O_NONBLOCK？</li><li>为什么用 fsync 也可能丢数据？</li><li>BBR 比 Cubic 收益在哪？</li></ul><p>每个问题都串多个抽象层：</p><ul><li>用 <strong>strace / perf / ftrace</strong> 看实际系统调用；</li><li>用 <strong>eBPF / bpftrace</strong> 看内核态内部；</li><li>拓到 <strong>CPU cache / NUMA / NVMe</strong> 物理层；</li><li>必要时引到 <strong>FPGA / SmartNIC</strong> 上的 bypass 路径。</li></ul><p>OS 的故事是硬件 + 抽象 + 工程现实反复折中。读完这一部分，看回去 DSA 里的 cache-friendly 那一段你会更顺，因为 OS 把那些底层都编程化了。</p>',11)])])}const u=e(r,[["render",o]]);export{f as __pageData,u as default};
